<div role="tabpanel" id="panel-lecturer" aria-labelledby="tab-lecturer" x-show="tab==='lecturer'" class="space-y-4"><div x-show="!lecturerTitles.length" class="text-center py-12 text-muted-foreground border rounded-lg border-dashed">No titles found matching your criteria.</div><div x-show="lecturerTitles.length" class="rounded-md border overflow-x-auto"><table class="w-full text-sm"><thead class="border-b"><tr>@foreach(['Project Title','Lecturer','Specs','Availability','Action'] as $head)<th class="h-10 px-2 text-left font-medium text-muted-foreground {{ $loop->last?'text-right':'' }}">{{ $head }}</th>@endforeach</tr></thead><tbody><template x-for="title in lecturerTitles" :key="title.id"><tr class="border-b last:border-0 group cursor-pointer hover:bg-muted/30" @click="open(title)"><td class="p-2 font-medium max-w-[350px]"><a :href="url('/mahasiswa/titles/'+title.id)" class="line-clamp-2" x-text="title.title"></a></td><td class="p-2 whitespace-nowrap" x-text="person(title.lecturer)"></td><td class="p-2"><div class="flex flex-wrap gap-1"><template x-for="spec in title.specializations || []" :key="spec"><x-capstone::badge variant="outline" class="text-[10px] h-5" x-text="spec" /></template></div></td><td class="p-2 text-xs whitespace-nowrap" x-text="Math.max(0,title.quota-(title.active_groups_count??0))+' of '+title.quota+' open'"></td><td class="p-2 text-right" @click.stop><x-capstone::button size="sm" @click="open(title)" ::disabled="!canBid || title.quota-(title.active_groups_count??0)<=0"><x-capstone::icon name="Lock" x-show="!canBid" class="h-3 w-3" /><span x-text="period?.is_finalized?'Closed':'View & Bid'"></span></x-capstone::button></td></tr></template></tbody></table></div></div>
